//! Publication of a verified stage to the dedicated public release bucket. Every expected hash
//! comes from the verification pass itself (the manifests it regenerated from the exact artifact
//! bytes it read), so nothing is trusted from a second look at the stage. Each versioned file is
//! read once more through the same no-follow helper, checked against that hash, and uploaded from
//! those bytes in memory; manifests upload straight from the regenerated bytes. Versioned objects
//! go first, each upload is read back and compared, and `latest.json` is written last, so no client
//! sees a manifest that points at a missing or different file. Published versions are never
//! overwritten.
use std::{
    io::Write,
    path::PathBuf,
    process::{Command, Stdio},
};

use anyhow::{Context, Result, bail, ensure};
use sha2::{Digest, Sha256};

use crate::{Channel, MAX_ARTIFACT, bounded, verify_stage};

/// Versioned objects never change once published.
pub const IMMUTABLE: &str = "public, max-age=31536000, immutable";
/// Channel manifests change with every release, so caches revalidate quickly.
pub const MANIFEST: &str = "public, max-age=60, must-revalidate";

#[derive(Debug, Clone, PartialEq, Eq)]
enum Source {
    /// A versioned file, read again only through the stage's no-follow helper.
    File { directory: PathBuf, name: String },
    /// A manifest exactly as verification regenerated it.
    Generated(Vec<u8>),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PublicObject {
    /// Bucket key, under the channel's prefix.
    pub key: String,
    pub content_type: &'static str,
    pub cache_control: &'static str,
    /// SHA-256 of the bytes verification accepted.
    pub sha256: String,
    source: Source,
}

impl PublicObject {
    fn immutable(&self) -> bool {
        self.cache_control == IMMUTABLE
    }

    /// The bytes to upload, refused unless they still hash to what verification accepted.
    fn read(&self) -> Result<Vec<u8>> {
        let bytes = match &self.source {
            Source::File { directory, name } => bounded(directory, name, MAX_ARTIFACT)?,
            Source::Generated(bytes) => bytes.clone(),
        };
        ensure!(
            hex(&bytes) == self.sha256,
            "{} changed after the stage was verified",
            self.key
        );
        Ok(bytes)
    }
}

/// Re-verifies the stage against the pinned key and lists its public objects in upload order:
/// every versioned object, then the channel's `SHA256SUMS` and `downloads.json`, then
/// `latest.json`. Local records (`release-plan.json`, `COMPLETE`) are never listed.
pub fn publication_plan(
    stage: &std::path::Path,
    expected_public_key: &str,
) -> Result<Vec<PublicObject>> {
    let verified = verify_stage(stage, expected_public_key)?;
    let prefix = match verified.plan.channel {
        Channel::Stable => "",
        Channel::Staging => "staging/",
    };
    let manifest = |name: &str| {
        verified
            .manifests
            .get(name)
            .cloned()
            .with_context(|| format!("Verification produced no {name}"))
    };
    let checksums = manifest("SHA256SUMS")?;
    // SHA256SUMS lists every package and signature by the hash of the exact bytes verified.
    let mut versioned = vec![(
        "SHA256SUMS".to_owned(),
        hex(&checksums),
        Source::Generated(checksums.clone()),
    )];
    for line in std::str::from_utf8(&checksums)?.lines() {
        let (hash, name) = line
            .split_once("  ")
            .context("Malformed verified checksum line")?;
        versioned.push((
            name.to_owned(),
            hash.to_owned(),
            Source::File {
                directory: verified.payload.clone(),
                name: name.to_owned(),
            },
        ));
    }
    versioned.sort_by(|a, b| a.0.cmp(&b.0));
    let mut objects = Vec::with_capacity(versioned.len() + 3);
    for (name, sha256, source) in versioned {
        let key = format!("{prefix}releases/{}/{name}", verified.plan.version);
        objects.push(PublicObject {
            content_type: content_type(&key),
            key,
            cache_control: IMMUTABLE,
            sha256,
            source,
        });
    }
    for name in ["SHA256SUMS", "downloads.json", "latest.json"] {
        let bytes = manifest(name)?;
        let key = format!("{prefix}{name}");
        objects.push(PublicObject {
            content_type: content_type(&key),
            key,
            cache_control: MANIFEST,
            sha256: hex(&bytes),
            source: Source::Generated(bytes),
        });
    }
    Ok(objects)
}

fn content_type(key: &str) -> &'static str {
    if key.ends_with(".json") {
        "application/json; charset=utf-8"
    } else if key.ends_with("SHA256SUMS") || key.ends_with(".sig") {
        "text/plain; charset=utf-8"
    } else if key.ends_with(".dmg") {
        "application/x-apple-diskimage"
    } else if key.ends_with(".exe") {
        "application/vnd.microsoft.portable-executable"
    } else if key.ends_with(".tar.gz") {
        "application/gzip"
    } else {
        "application/octet-stream"
    }
}

fn hex(bytes: &[u8]) -> String {
    format!("{:x}", Sha256::digest(bytes))
}

/// Where public objects are written and read back.
pub trait Transport {
    /// The object's bytes, or `None` when the key does not exist.
    fn get(&self, key: &str) -> Result<Option<Vec<u8>>>;
    /// Uploads exactly `bytes` under the object's key with its content type and cache policy.
    fn put(&self, object: &PublicObject, bytes: &[u8]) -> Result<()>;
}

#[derive(Debug, Default, PartialEq, Eq)]
pub struct Report {
    pub uploaded: Vec<String>,
    /// Versioned objects already published with identical bytes (a resumed publication).
    pub already_present: Vec<String>,
}

/// Uploads `objects` in order. Before anything is written, every object is read once and checked
/// against its verified hash, and every versioned key is checked in the bucket: an existing key
/// must already hold identical bytes, or publication stops untouched. Each upload is read back and
/// compared before the next, so a failure always stops before `latest.json`.
pub fn publish(objects: &[PublicObject], transport: &impl Transport) -> Result<Report> {
    ensure!(
        objects
            .last()
            .is_some_and(|last| last.key.ends_with("latest.json")),
        "latest.json must be the last object published"
    );
    let payloads = objects
        .iter()
        .map(PublicObject::read)
        .collect::<Result<Vec<_>>>()?;
    let mut present = Vec::new();
    for object in objects.iter().filter(|object| object.immutable()) {
        if let Some(existing) = transport.get(&object.key)? {
            ensure!(
                hex(&existing) == object.sha256,
                "{} is already published with different bytes. Published versions are never overwritten; choose a new version.",
                object.key
            );
            present.push(object.key.clone());
        }
    }
    let mut report = Report::default();
    for (object, bytes) in objects.iter().zip(&payloads) {
        if present.contains(&object.key) {
            report.already_present.push(object.key.clone());
            continue;
        }
        transport.put(object, bytes)?;
        let Some(back) = transport.get(&object.key)? else {
            bail!("{} is missing right after upload", object.key);
        };
        ensure!(
            hex(&back) == object.sha256,
            "{} reads back with different bytes; publication stopped before latest.json",
            object.key
        );
        report.uploaded.push(object.key.clone());
    }
    Ok(report)
}

/// The repository's pinned Wrangler, run through Node directly so no shell parses the arguments.
/// Uploads stream from memory over stdin, never from a path that could change underneath. It uses
/// the release operator's own Cloudflare sign-in; no credential passes through here.
pub struct Wrangler {
    pub node: PathBuf,
    pub script: PathBuf,
    pub bucket: String,
}

impl Wrangler {
    fn command(&self, args: &[&str]) -> Command {
        let mut command = Command::new(&self.node);
        command.arg(&self.script).args(args);
        command
    }
}

impl Transport for Wrangler {
    fn get(&self, key: &str) -> Result<Option<Vec<u8>>> {
        let target = format!("{}/{key}", self.bucket);
        let output = self
            .command(&["r2", "object", "get", &target, "--pipe", "--remote"])
            .output()
            .with_context(|| format!("Could not start Wrangler at {}", self.script.display()))?;
        if output.status.success() {
            return Ok(Some(output.stdout));
        }
        let error = String::from_utf8_lossy(&output.stderr);
        if error.contains("does not exist") || error.contains("NoSuchKey") {
            return Ok(None);
        }
        bail!("Wrangler could not read {target}: {}", error.trim())
    }

    fn put(&self, object: &PublicObject, bytes: &[u8]) -> Result<()> {
        let target = format!("{}/{}", self.bucket, object.key);
        let mut child = self
            .command(&[
                "r2",
                "object",
                "put",
                &target,
                "--pipe",
                "--content-type",
                object.content_type,
                "--cache-control",
                object.cache_control,
                "--remote",
            ])
            .stdin(Stdio::piped())
            .stdout(Stdio::null())
            .stderr(Stdio::piped())
            .spawn()
            .with_context(|| format!("Could not start Wrangler at {}", self.script.display()))?;
        child
            .stdin
            .take()
            .context("Wrangler's input closed early")?
            .write_all(bytes)?;
        let output = child.wait_with_output()?;
        ensure!(
            output.status.success(),
            "Wrangler could not upload {target}: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        );
        Ok(())
    }
}
